import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_DIGITS = "0123456789"
_ZIP_PLUS4 = re.compile(r"[0-9]{4,5}-[0-9]{4}")
_ANGLE = re.compile(r"<([^<>]*)>")


def _s(row, key):
    v = row.get(key)
    return "" if v is None else str(v)


def _is_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = raw.strip()
    m = _ANGLE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        i = s.find(marker)
        if i != -1:
            cut = min(cut, i)
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = raw.strip()
    if _ZIP_PLUS4.fullmatch(s):
        s = s.split("-")[0]
    if len(s) == 4 and _is_digits(s):
        s = "0" + s
    return s if len(s) == 5 and _is_digits(s) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unparseable 'updated' value: {raw!r}")


def _opted_out(raw):
    return raw.strip().lower() in {"y", "yes", "true", "1"}


def _parse_tags(raw):
    parts = re.split(r"[;,]", raw)
    return {p.strip().lower() for p in parts if p.strip()}


def dedupe_contacts(rows):
    # Step 1: normalize rows and drop those with no valid email or phone.
    recs = []
    for row in rows:
        email = _normalize_email(_s(row, "email"))
        if not _valid_email(email):
            email = ""
        phone = _normalize_phone(_s(row, "phone"))
        if not _valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue

        source = _s(row, "source").strip().lower()
        recs.append({
            "first_name": _normalize_name(_s(row, "first_name")),
            "last_name": _normalize_name(_s(row, "last_name")),
            "zip": _normalize_zip(_s(row, "zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(_s(row, "tags")),
            "opted_out": _opted_out(_s(row, "opted_out")),
            "updated": _parse_updated(_s(row, "updated")),
        })

    # Step 2: group rows into people with union-find (transitive matching).
    n = len(recs)
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    seen = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email"]:
            keys.append(("email", r["email"]))
        if r["phone"] and r["last_name"]:
            keys.append(("phone", r["phone"], r["last_name"].casefold()))
        for k in keys:
            if k in seen:
                union(i, seen[k])
            else:
                seen[k] = i

    # Collect groups, ordered by each group's earliest row.
    groups = {}
    order = []
    for i in range(n):
        root = find(i)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(i)

    # Step 3: pick field values and build output.
    def pick(members, field):
        cands = [i for i in members if recs[i][field]]
        if not cands:
            return ""
        # Prefer manual rows, then latest updated, then earliest input row.
        best = max(
            cands,
            key=lambda i: (recs[i]["manual"], recs[i]["updated"], -i),
        )
        return recs[best][field]

    out = []
    for root in order:
        members = groups[root]
        tags = set()
        for i in members:
            tags |= recs[i]["tags"]
        latest = max(recs[i]["updated"] for i in members)
        out.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in members) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return out
